If $f$ satisfies Assumption \ref{as:smooth}, then for any $x,y$,
\[
f(x)\le f(y)+\ip{\grad f(y)}{x-y}+L\D(x,y).
\]
\end{lemma}
\begin{proof}
Assumption \ref{as:smooth} is precisely the inequality above; therefore the lemma follows directly. \hfill\qedsymbol
\end{proof}
\begin{lemma}[Optimality condition of the mirror step]\label{lem:opt}
Let $x_{k+1}$ be defined by \eqref{eq:update}. Then for any $x$,
\[
\ip{\grad f(x_k)}{x_{k+1}-x}+ \frac{1}{\eta_k}\bigl[\D(x,x_k)-\D(x,x_{k+1})-\D(x_{k+1},x_k)\bigr]\ge0.
\]
\end{lemma}
\begin{proof}
Because $x_{k+1}$ minimises the convex function $x\mapsto \ip{\grad f(x_k)}{x}+\frac{1}{\eta_k}\D(x,x_k)$, the first‑order optimality condition yields
\[
\ip{\grad f(x_k)}{x-x_{k+1}}+\frac{1}{\eta_k}\ip{\grad h(x_{k+1})-\grad h(x_k)}{x-x_{k+1}}\ge0.
\]
Rearranging and invoking the definition of $\D$ gives the claimed inequality. \hfill\qedsymbol
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We now prove Theorem \ref{thm:main}. Throughout the proof we fix an arbitrary $K\ge1$.

\bigskip
\noindent\textbf{[Step 1]} Apply Lemma \ref{lem:opt} with $x=x_k$:
\[
\ip{\grad f(x_k)}{x_{k+1}-x_k}+ \frac{1}{\eta_k}\bigl[\D(x_k,x_k)-\D(x_k,x_{k+1})-\D(x_{k+1},x_k)\bigr]\ge0.
\]
Since $\D(x_k,x_k)=0$, we obtain
\[
\ip{\grad f(x_k)}{x_{k+1}-x_k}\ge
-\frac{1}{\eta_k}\bigl[\D(x_k,x_{k+1})+\D(x_{k+1},x_k)\bigr].
\]
Multiplying by $-1$ and using the three‑point identity \eqref{eq:threepoint} gives the *correct* lower bound
\begin{equation}
\label{eq:step1}
\ip{\grad f(x_k)}{x_k-x_{k+1}}
\;\ge\;
\frac{1}{\eta_k}\bigl[\D(x_k,x_{k+1})+\D(x_{k+1},x_k)\bigr].
\end{equation}
% CORRECTED: removed the false symmetry claim and employed the three‑point identity.

\bigskip
\noindent\textbf{[Step 2]} Use Lemma \ref{lem:descent} with $y=x_k$ and $x=x_{k+1}$:
\[
f(x_{k+1})\le f(x_k)+\ip{\grad f(x_k)}{x_{k+1}-x_k}+L\D(x_{k+1},x_k).
\]
Insert the lower bound \eqref{eq:step1} (after moving the inner product to the right‑hand side):
\begin{equation}
\label{eq:step2}
f(x_{k+1})\le f(x_k)-\frac{1}{\eta_k}\bigl[\D(x_k,x_{k+1})+\D(x_{k+1},x_k)\bigr]+L\D(x_{k+1},x_k).
\end{equation}
Rearranging,
\begin{equation}
\label{eq:step2b}
f(x_k)-f(x_{k+1})
\ge
\Bigl(\frac{1}{\eta_k}-L\Bigr)\D(x_{k+1},x_k)+\frac{1}{\eta_k}\D(x_k,x_{k+1}).
\end{equation}

\bigskip
\noindent\textbf{[Step 3]} By Assumption \ref{as:stepsize} we have $\eta_k\le\frac{1}{2L}$, hence
\[
\frac{1}{\eta_k}-L\;=\;\frac{1-\eta_k L}{\eta_k}\;\ge\;\frac{1}{2\eta_k}.
\]
Therefore both coefficients in \eqref{eq:step2b} are at least $\frac{1}{2\eta_k}$, and we obtain the clean inequality
\begin{equation}
\label{eq:step3}
f(x_k)-f(x_{k+1})
\;\ge\;
\frac{1}{2\eta_k}\Bigl[\D(x_k,x_{k+1})+\D(x_{k+1},x_k)\Bigr].
\end{equation}
% CORRECTED: the sign issue is resolved and the bound follows from the explicit stepsize condition.

\bigskip
\noindent\textbf{[Step 4]} Relate the Bregman distances to the gradient mapping. By definition of $G_{\eta_k}(x_k)$ and the optimality condition,
\[
x_{k+1}=x_k-\eta_k G_{\eta_k}(x_k).
\]
Strong convexity of $h$ (Assumption \ref{as:hstrong}) yields
\[
\D(x_k,x_{k+1})\ge\frac{\alpha}{2}\|x_k-x_{k+1}\|^{2},
\qquad
\D(x_{k+1},x_k)\ge\frac{\alpha}{2}\|x_k-x_{k+1}\|^{2}.
\]
Adding the two inequalities and using $x_k-x_{k+1}=\eta_k G_{\eta_k}(x_k)$ gives
\[
\D(x_k,x_{k+1})+\D(x_{k+1},x_k)
\;\ge\;
\alpha\eta_k^{2}\norm{G_{\eta_k}(x_k)}_{*}^{2}.
\]
Insert this bound into \eqref{eq:step3}:
\begin{equation}
\label{eq:step4}
f(x_k)-f(x_{k+1})
\;\ge\;
\frac{\alpha\eta_k}{2}\norm{G_{\eta_k}(x_k)}_{*}^{2}.
\end{equation}
% CORRECTED: the factor $\frac{\alpha\eta_k}{2}$ follows from the sum of the two divergences.

\bigskip
\noindent\textbf{[Step 5]} Take expectations on both sides of \eqref{eq:step4} (the algorithm may be stochastic; in the deterministic case the expectation operator is redundant) and sum over $k=0,\dots,K-1$:
\[
\sum_{k=0}^{K-1}\E\!\bigl[f(x_k)-f(x_{k+1})\bigr]
\;=\;
\E\!\bigl[f(x_0)-f(x_K)\bigr]
\;\ge\;
\frac{\alpha}{2}\sum_{k=0}^{K-1}\eta_k\,\E\!\bigl[\norm{G_{\eta_k}(x_k)}_{*}^{2}\bigr].
\]
Since $f(x_K)\ge f^{\inf}$,
\begin{equation}
\label{eq:step5}
\sum_{k=0}^{K-1}\eta_k\,\E\!\bigl[\norm{G_{\eta_k}(x_k)}_{*}^{2}\bigr]
\;\le\;
\frac{2}{\alpha}\bigl(\E[f(x_0)]-f^{\inf}\bigr).
\end{equation}

\bigskip
\noindent\textbf{[Step 6]} Use the *uniform* stepsize $\eta_k\equiv\eta=\frac{1}{2L}$ (the largest value allowed by Assumption \ref{as:stepsize}). Then $\eta_k=\eta$ for all $k$ and \eqref{eq:step5} becomes
\[
\eta\sum_{k=0}^{K-1}\E\!\bigl[\norm{G_{\eta}(x_k)}_{*}^{2}\bigr]
\le
\frac{2}{\alpha}\bigl(\E[f(x_0)]-f^{\inf}\bigr).
\]
Dividing by $\eta K$ and recalling that $\eta=1/(2L)$ yields the averaged bound
\begin{equation}
\label{eq:final}
\frac{1}{K}\sum_{k=0}^{K-1}\E\!\bigl[\norm{G_{\eta}(x_k)}_{*}^{2}\bigr]
\le
\frac{4L}{\alpha K}\,\bigl(\E[f(x_0)]-f^{\inf}\bigr),
\end{equation}
which is exactly \eqref{eq:averaged-bound}. The claimed $O(1/K)$ rate follows immediately.

\hfill\qedsymbol

\section*{Rate Derivation (With Constants)}
From \eqref{eq:final},
\[
\min_{0\le k\le K-1}\E\!\bigl[\norm{G_{\eta}(x_k)}_{*}^{2}\bigr]
\;\le\;
\frac{1}{K}\sum_{k=0}^{K-1}\E\!\bigl[\norm{G_{\eta}(x_k)}_{*}^{2}\bigr]
\;\le\;
\frac{4L}{\alpha K}\bigl(\E[f(x_0)]-f^{\inf}\bigr).
\]
Thus the algorithm attains the optimal sub‑linear $O(1/K)$ rate for first‑order methods on smooth non‑convex objectives, with constants explicitly depending on the smoothness constant $L$, the strong‑convexity modulus $\alpha$ of the prox‑function, and the initial optimality gap.

\section*{Special Cases}
\begin{enumerate}
\item \textbf{Euclidean setting.} $h(x)=\frac12\|x\|^{2}$ gives $\alpha=1$, $\D(x,y)=\frac12\|x-y\|^{2}$, and $G_{\eta}(x_k)=\grad f(x_k)$. The theorem reduces to the classic result $\frac{1}{K}\sum_{k}\norm{\grad f(x_k)}^{2}=O(1/K)$.
\item \textbf{Negative entropy on the simplex.} For $h(x)=\sum_{i}x_i\log x_i$, $\alpha=1$ w.r.t. $\ell_{1}$ norm, and $G_{\eta}$ corresponds to the natural gradient in the probability simplex. The same $O(1/K)$ bound holds, showing the benefit of geometry‑aware updates.
\item \textbf{Adaptive stepsizes.} If $\eta_k=\frac{1}{2L}\frac{1}{\sqrt{k+1}}$, the same derivation leads to a $O(1/\sqrt{K})$ bound for the *average* gradient‑mapping norm, matching known results for diminishing stepsizes.
\end{enumerate}

